def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if out[r][c] != 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and out[nr][nc] == 5 and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            r0 = min(rr for rr, _ in cells)
            r1 = max(rr for rr, _ in cells)
            c0 = min(cc for _, cc in cells)
            c1 = max(cc for _, cc in cells)
            gaps = [cc for cc in range(c0, c1 + 1) if out[r0][cc] != 5]
            if not gaps:
                continue
            gap = gaps[0]
            left = sum(out[r0][cc] == 5 for cc in range(c0, gap))
            right = sum(out[r0][cc] == 5 for cc in range(gap + 1, c1 + 1))
            for rr in range(r0, r1 + 1):
                for cc in range(c0, c1 + 1):
                    if out[rr][cc] == 0:
                        out[rr][cc] = 2
            if r0 > 0:
                if left >= right:
                    for cc in range(gap, -1, -1):
                        out[r0 - 1][cc] = 2
                else:
                    for cc in range(gap, w):
                        out[r0 - 1][cc] = 2
    return out
